//! 🎞️ GIF89a's individually authored animation and extension SQLite projection.
use super::*;
use semio_framework_os_kernel::{sqlite_snapshot::{artifact::{Cell, Projection, reconstruct_text, ordered_row_refs}, validate_sqlite_database_schema, SqliteDatabase, SqliteRow, SqliteSnapshotControl, SqliteSnapshotPhase, SqliteValue}, ArtifactSqliteSnapshot};
use std::collections::{BTreeMap,BTreeSet};

fn unsigned(row:&SqliteRow,column:usize)->Result<u32,String>{u32::try_from(row.integer(column)?).map_err(|error|error.to_string())}
fn word(row:&SqliteRow,column:usize)->Result<u16,String>{u16::try_from(row.integer(column)?).map_err(|error|error.to_string())}
fn byte(row:&SqliteRow,column:usize)->Result<u8,String>{u8::try_from(row.integer(column)?).map_err(|error|error.to_string())}
fn flag(row:&SqliteRow,column:usize)->Result<bool,String>{match row.integer(column)?{0=>Ok(false),1=>Ok(true),_=>Err("GIF89 boolean must be zero or one".into())}}
fn optional_word(row:&SqliteRow,column:usize)->Result<Option<u16>,String>{match row.values.get(column){Some(SqliteValue::Null)=>Ok(None),_=>word(row,column).map(Some)}}
fn optional_byte(row:&SqliteRow,column:usize)->Result<Option<u8>,String>{match row.values.get(column){Some(SqliteValue::Null)=>Ok(None),_=>byte(row,column).map(Some)}}
fn count(width:u32,height:u32)->Result<usize,String>{usize::try_from(u64::from(width)*u64::from(height)).map_err(|error|error.to_string())}
fn entities<'a>(database:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<&'a [SqliteRow],String>{let rows=&database.table(table)?.rows;let mut keys=BTreeSet::new();for(position,row)in rows.iter().enumerate(){if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,rows.len())?;}if row.rowid<=0||row.integer(0)?!=row.rowid||!keys.insert(row.rowid){return Err("GIF89 entities require unique positive aliased identifiers".into());}}Ok(rows)}
fn identifiers(rows:impl IntoIterator<Item=i64>,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeSet<i64>,String>{let mut keys=BTreeSet::new();for(position,key)in rows.into_iter().enumerate(){if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,0)?;}keys.insert(key);}Ok(keys)}
fn one_to_one<'a>(rows:&'a [SqliteRow],parents:&BTreeSet<i64>,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,&'a SqliteRow>,String>{let mut out=BTreeMap::new();for(position,row)in rows.iter().enumerate(){if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,rows.len())?;}if !parents.contains(&row.rowid)||out.insert(row.rowid,row).is_some(){return Err("GIF89 one-to-one relationship has an unknown or duplicate owner".into());}}Ok(out)}
fn groups<'a>(rows:&'a [SqliteRow],parents:&BTreeSet<i64>,ordered:bool,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<&'a SqliteRow>>,String>{let mut groups=BTreeMap::<i64,Vec<&SqliteRow>>::new();for(position,row)in rows.iter().enumerate(){if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,rows.len())?;}let owner=row.integer(1)?;if !parents.contains(&owner){return Err("GIF89 child has an unknown owner".into());}groups.entry(owner).or_default().push(row);}if ordered{for rows in groups.values_mut(){let mut slots=vec![None;rows.len()];for(position,row)in rows.iter().enumerate(){if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,rows.len())?;}let ordinal=usize::try_from(row.integer(2)?).map_err(|error|error.to_string())?;let slot=slots.get_mut(ordinal).ok_or("GIF89 child ordinals must be dense")?;if slot.replace(*row).is_some(){return Err("GIF89 child ordinals must be unique".into());}}let total=slots.len();rows.clear();for(position,row)in slots.into_iter().enumerate(){if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,total)?;}rows.push(row.ok_or("GIF89 child ordinals must be dense")?);}}}Ok(groups)}
fn palette(out:&mut Projection<'_,'_>,header:&str,entries:&str,owner:i64,palette:&Option<GifColorTable>)->Result<(),String>{if let Some(palette)=palette{out.insert_key(header,owner,&[Cell::Integer(i64::from(palette.sorted))])?;for(ordinal,color)in palette.colors.iter().enumerate(){out.insert(entries,&[Cell::Integer(owner),Cell::Integer(ordinal as i64),Cell::Integer(color.r.into()),Cell::Integer(color.g.into()),Cell::Integer(color.b.into())])?;}}Ok(())}
fn read_palette(header:Option<&&SqliteRow>,colors:Option<&Vec<&SqliteRow>>,control:&mut SqliteSnapshotControl<'_>)->Result<Option<GifColorTable>,String>{let Some(header)=header else{return Ok(None)};let mut entries=Vec::new();for row in colors.into_iter().flatten(){if entries.len()%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,entries.len(),0)?;}entries.push(GifRgb{r:byte(row,3)?,g:byte(row,4)?,b:byte(row,5)?});}Ok(Some(GifColorTable{sorted:flag(header,1)?,colors:entries}))}
fn read_pixels(rows:Option<&Vec<&SqliteRow>>,width:u32,height:u32,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<u8>,String>{let expected=count(width,height)?;let rows=rows.map(Vec::as_slice).unwrap_or_default();if rows.len()!=expected{return Err("GIF89 frame requires one palette index per grid position".into());}let mut indices=vec![0;expected];let mut seen=vec![false;expected];for(ordinal,row)in rows.iter().enumerate(){if ordinal%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,ordinal,expected)?;}let x=unsigned(row,2)?;let y=unsigned(row,3)?;if x>=width||y>=height{return Err("GIF89 pixel exceeds its frame grid".into());}let position=usize::try_from(u64::from(y)*u64::from(width)+u64::from(x)).map_err(|error|error.to_string())?;if std::mem::replace(&mut seen[position],true){return Err("GIF89 pixel coordinates must be unique".into());}indices[position]=byte(row,4)?;}Ok(indices)}
fn disposal(value:GifDisposal)->&'static str{match value{GifDisposal::Unspecified=>"unspecified",GifDisposal::DoNotDispose=>"do_not_dispose",GifDisposal::RestoreToBackground=>"restore_to_background",GifDisposal::RestoreToPrevious=>"restore_to_previous"}}
fn read_disposal(value:&str)->Result<GifDisposal,String>{match value{"unspecified"=>Ok(GifDisposal::Unspecified),"do_not_dispose"=>Ok(GifDisposal::DoNotDispose),"restore_to_background"=>Ok(GifDisposal::RestoreToBackground),"restore_to_previous"=>Ok(GifDisposal::RestoreToPrevious),_=>Err("unknown GIF89 disposal policy".into())}}
fn read_plain_text(row:Option<&&SqliteRow>,control:&mut SqliteSnapshotControl<'_>)->Result<Option<GifPlainText>,String>{row.map(|row|Ok(GifPlainText{left:unsigned(row,1)?,top:unsigned(row,2)?,width:unsigned(row,3)?,height:unsigned(row,4)?,cell_width:byte(row,5)?,cell_height:byte(row,6)?,fg_color_index:byte(row,7)?,bg_color_index:byte(row,8)?,text:reconstruct_text(control,row.text(9)?)?})).transpose()}

impl ArtifactSqliteSnapshot for GifSnapshot{
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::io_schema::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;if dialect.artifact_kind!="s.stdio.gif"||dialect.standard!="89a"||!matches!(dialect.subset.as_str(),"*"|"base"){return Err(format!("GIF89a does not own semantic subset {}",dialect.to_coordinate()).into());}if database.table("gif89_document")?.single_row()?.text(1)?!=self.schema{return Err("GIF89a semantic document identity disagrees with its snapshot".to_string().into());}Ok(store::io_schema::IoOutcome::clean(()))}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
  let mut out=Projection::new(Self::SQLITE_SCHEMA,control)?;
  out.insert("gif89_document",&[Cell::Text(&self.schema),Cell::Integer(self.width.into()),Cell::Integer(self.height.into()),Cell::Integer(self.background_color_index.into()),Cell::Integer(self.pixel_aspect_ratio.into()),self.loop_count.map(|value|Cell::Integer(value.into())).unwrap_or(Cell::Null)])?;
  palette(&mut out,"gif89_global_palette","gif89_global_color",1,&self.gct)?;
  for(ordinal,frame)in self.frames.iter().enumerate(){if count(frame.width,frame.height)?!=frame.indices.len(){return Err("GIF89 frame requires one palette index per grid position".into());}
   let id=out.insert("gif89_frame",&[Cell::Integer(1),Cell::Integer(ordinal as i64),Cell::Integer(frame.left.into()),Cell::Integer(frame.top.into()),Cell::Integer(frame.width.into()),Cell::Integer(frame.height.into()),Cell::Integer(i64::from(frame.interlace)),Cell::Integer(frame.delay_cs.into()),Cell::Text(disposal(frame.disposal)),frame.transparent_index.map(|value|Cell::Integer(value.into())).unwrap_or(Cell::Null),Cell::Integer(i64::from(frame.user_input))])?;
   palette(&mut out,"gif89_local_palette","gif89_local_color",id,&frame.lct)?;
   for(position,index)in frame.indices.iter().enumerate(){out.insert("gif89_pixel",&[Cell::Integer(id),Cell::Integer((position as u64%u64::from(frame.width))as i64),Cell::Integer((position as u64/u64::from(frame.width))as i64),Cell::Integer((*index).into())])?;}
   if let Some(text)=&frame.plain_text{out.insert_key("gif89_plain_text",id,&[Cell::Integer(text.left.into()),Cell::Integer(text.top.into()),Cell::Integer(text.width.into()),Cell::Integer(text.height.into()),Cell::Integer(text.cell_width.into()),Cell::Integer(text.cell_height.into()),Cell::Integer(text.fg_color_index.into()),Cell::Integer(text.bg_color_index.into()),Cell::Text(&text.text)])?;}
  }
  for(ordinal,text)in self.comments.iter().enumerate(){out.insert("gif89_comment",&[Cell::Integer(1),Cell::Integer(ordinal as i64),Cell::Text(text)])?;}
  for(ordinal,application)in self.app_extensions.iter().enumerate(){let a=&application.identifier;let b=&application.auth_code;let id=out.insert("gif89_application",&[Cell::Integer(1),Cell::Integer(ordinal as i64),Cell::Integer(a[0].into()),Cell::Integer(a[1].into()),Cell::Integer(a[2].into()),Cell::Integer(a[3].into()),Cell::Integer(a[4].into()),Cell::Integer(a[5].into()),Cell::Integer(a[6].into()),Cell::Integer(a[7].into()),Cell::Integer(b[0].into()),Cell::Integer(b[1].into()),Cell::Integer(b[2].into())])?;for(ordinal,value)in application.data.iter().enumerate(){out.insert("gif89_application_byte",&[Cell::Integer(id),Cell::Integer(ordinal as i64),Cell::Integer((*value).into())])?;}}
  out.finish()
 }
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
  validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits()).map_err(|error|error.to_string())?;control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;
  let document=database.table("gif89_document")?.single_row()?;if document.rowid!=1||document.integer(0)?!=1{return Err("GIF89 document identity must be one".into());}
  let frame_rows=entities(database,"gif89_frame",control)?;let frame_ids=identifiers(frame_rows.iter().map(|row|row.rowid),control)?;let document_ids=BTreeSet::from([1]);
  let global=one_to_one(entities(database,"gif89_global_palette",control)?,&document_ids,control)?;let global_ids=identifiers(global.keys().copied(),control)?;let global_colors=groups(entities(database,"gif89_global_color",control)?,&global_ids,true,control)?;
  let local=one_to_one(entities(database,"gif89_local_palette",control)?,&frame_ids,control)?;let local_ids=identifiers(local.keys().copied(),control)?;let local_colors=groups(entities(database,"gif89_local_color",control)?,&local_ids,true,control)?;
  let pixels=groups(entities(database,"gif89_pixel",control)?,&frame_ids,false,control)?;let texts=one_to_one(entities(database,"gif89_plain_text",control)?,&frame_ids,control)?;let mut frames=Vec::new();
  for row in ordered_row_refs(database.table("gif89_frame")?,2,control)?{if row.integer(1)?!=1{return Err("GIF89 frame has an unknown document".into());}control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,frames.len(),frame_rows.len())?;let width=unsigned(row,5)?;let height=unsigned(row,6)?;frames.push(GifFrame{left:unsigned(row,3)?,top:unsigned(row,4)?,width,height,interlace:flag(row,7)?,lct:read_palette(local.get(&row.rowid),local_colors.get(&row.rowid),control)?,indices:read_pixels(pixels.get(&row.rowid),width,height,control)?,delay_cs:word(row,8)?,disposal:read_disposal(row.text(9)?)?,transparent_index:optional_byte(row,10)?,user_input:flag(row,11)?,plain_text:read_plain_text(texts.get(&row.rowid),control)?});}
  entities(database,"gif89_comment",control)?;let mut comments=Vec::new();for row in ordered_row_refs(database.table("gif89_comment")?,2,control)?{if row.integer(1)?!=1{return Err("GIF89 comment has an unknown document".into());}if comments.len()%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,comments.len(),0)?;}comments.push(reconstruct_text(control,row.text(3)?)?);}
  let application_rows=entities(database,"gif89_application",control)?;let application_ids=identifiers(application_rows.iter().map(|row|row.rowid),control)?;let bytes=groups(entities(database,"gif89_application_byte",control)?,&application_ids,true,control)?;let mut app_extensions=Vec::new();
  for row in ordered_row_refs(database.table("gif89_application")?,2,control)?{if row.integer(1)?!=1{return Err("GIF89 application has an unknown document".into());}if app_extensions.len()%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,app_extensions.len(),application_rows.len())?;}let mut data=Vec::new();for row in bytes.get(&row.rowid).into_iter().flatten(){if data.len()%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,data.len(),0)?;}data.push(byte(row,3)?);}app_extensions.push(GifAppExtension{identifier:[byte(row,3)?,byte(row,4)?,byte(row,5)?,byte(row,6)?,byte(row,7)?,byte(row,8)?,byte(row,9)?,byte(row,10)?],auth_code:[byte(row,11)?,byte(row,12)?,byte(row,13)?],data});}
  let result=Self{schema:reconstruct_text(control,document.text(1)?)?,width:unsigned(document,2)?,height:unsigned(document,3)?,gct:read_palette(global.get(&1),global_colors.get(&1),control)?,background_color_index:byte(document,4)?,pixel_aspect_ratio:byte(document,5)?,loop_count:optional_word(document,6)?,frames,comments,app_extensions};control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,frame_rows.len(),frame_rows.len())?;Ok(result)
 }
}
